import React, { useEffect, useState } from "react";
import axios from "axios";

const API_BASE_URL = "http://localhost:9091";

function AdminDashboard({ onLogout }) {
  const [medicines, setMedicines] = useState([]);
  const [newMed, setNewMed] = useState({
    name: "",
    description: "",
    price: "",
    stock: "",
  });
  const [editMed, setEditMed] = useState(null); // 👈 for editing
  const [message, setMessage] = useState("");

  // ✅ Fetch all medicines
  const fetchMedicines = () => {
    axios
      .get(`${API_BASE_URL}/api/medicines`)
      .then((res) => setMedicines(res.data))
      .catch(() => setMessage("❌ Error fetching medicines"));
  };

  useEffect(() => {
    fetchMedicines();
  }, []);

  // ✅ Handle input change
  const handleChange = (e) => {
    setNewMed({ ...newMed, [e.target.name]: e.target.value });
  };

  // ✅ Add new medicine
  const handleSubmit = (e) => {
    e.preventDefault();
    axios
      .post(`${API_BASE_URL}/api/medicines`, newMed)
      .then(() => {
        setMessage("✅ Medicine added successfully!");
        setNewMed({ name: "", description: "", price: "", stock: "" });
        fetchMedicines();
      })
      .catch(() => setMessage("❌ Error adding medicine"));
  };

  // ✅ Edit medicine
  const handleEdit = (id, updatedMedicine) => {
    axios
      .put(`${API_BASE_URL}/api/medicines/${id}`, updatedMedicine)
      .then(() => {
        setMessage("✏️ Medicine updated successfully!");
        setEditMed(null);
        fetchMedicines();
      })
      .catch(() => setMessage("❌ Error updating medicine"));
  };

  // ✅ Delete medicine
  const handleDelete = (id) => {
    axios
      .delete(`${API_BASE_URL}/api/medicines/${id}`)
      .then(() => {
        setMessage("🗑️ Medicine deleted successfully!");
        fetchMedicines();
      })
      .catch(() => setMessage("❌ Error deleting medicine"));
  };

  return (
    <div className="p-6 max-w-6xl mx-auto">
      {/* ✅ Header */}
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-3xl font-bold text-indigo-700">Admin Dashboard</h2>
        <button
          onClick={onLogout}
          className="bg-red-500 text-white px-4 py-2 rounded-lg hover:bg-red-600"
        >
          Logout
        </button>
      </div>

      {/* ✅ Message Display */}
      {message && (
        <div className="bg-indigo-100 text-indigo-800 p-2 text-center mb-4 rounded">
          {message}
        </div>
      )}

      {/* ✅ Add Medicine Form */}
      <form
        onSubmit={handleSubmit}
        className="bg-white shadow-md rounded-lg p-4 mb-6"
      >
        <h3 className="text-xl font-semibold mb-3 text-gray-700">
          ➕ Add New Medicine
        </h3>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <input
            type="text"
            name="name"
            value={newMed.name}
            onChange={handleChange}
            placeholder="Name"
            className="border p-2 rounded"
            required
          />
          <input
            type="text"
            name="description"
            value={newMed.description}
            onChange={handleChange}
            placeholder="Description"
            className="border p-2 rounded"
            required
          />
          <input
            type="number"
            name="price"
            value={newMed.price}
            onChange={handleChange}
            placeholder="Price"
            className="border p-2 rounded"
            required
          />
          <input
            type="number"
            name="stock"
            value={newMed.stock}
            onChange={handleChange}
            placeholder="Stock"
            className="border p-2 rounded"
            required
          />
        </div>
        <button
          type="submit"
          className="mt-4 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition"
        >
          Add Medicine
        </button>
      </form>

      {/* ✅ Medicine List Table */}
      <div className="bg-white shadow-md rounded-lg p-4">
        <h3 className="text-xl font-semibold mb-3 text-gray-700">
          Medicine Inventory
        </h3>
        <table className="min-w-full border">
          <thead>
            <tr className="bg-indigo-100 text-gray-700">
              <th className="py-2 px-3 border">ID</th>
              <th className="py-2 px-3 border">Name</th>
              <th className="py-2 px-3 border">Description</th>
              <th className="py-2 px-3 border">Price</th>
              <th className="py-2 px-3 border">Stock</th>
              <th className="py-2 px-3 border">Actions</th>
            </tr>
          </thead>
          <tbody>
            {medicines.map((med) => (
              <tr key={med.id} className="text-center border-t">
                <td className="py-2 px-3 border">{med.id}</td>
                <td className="py-2 px-3 border">{med.name}</td>
                <td className="py-2 px-3 border">{med.description}</td>
                <td className="py-2 px-3 border">₹{med.price}</td>
                <td className="py-2 px-3 border">{med.stock}</td>
                <td className="py-2 px-3 border space-x-2">
                  <button
                    onClick={() => setEditMed(med)}
                    className="bg-blue-500 text-white px-3 py-1 rounded hover:bg-blue-600"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => handleDelete(med.id)}
                    className="bg-red-500 text-white px-3 py-1 rounded hover:bg-red-600"
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* ✅ Edit Medicine Form */}
      {editMed && (
        <div className="bg-gray-50 p-4 rounded-lg shadow-md mt-6">
          <h3 className="text-lg font-semibold mb-3 text-gray-700">
            ✏️ Edit Medicine (ID: {editMed.id})
          </h3>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <input
              type="text"
              value={editMed.name}
              onChange={(e) => setEditMed({ ...editMed, name: e.target.value })}
              className="border p-2 rounded"
              placeholder="Name"
            />
            <input
              type="text"
              value={editMed.description}
              onChange={(e) =>
                setEditMed({ ...editMed, description: e.target.value })
              }
              className="border p-2 rounded"
              placeholder="Description"
            />
            <input
              type="number"
              value={editMed.price}
              onChange={(e) =>
                setEditMed({ ...editMed, price: e.target.value })
              }
              className="border p-2 rounded"
              placeholder="Price"
            />
            <input
              type="number"
              value={editMed.stock}
              onChange={(e) =>
                setEditMed({ ...editMed, stock: e.target.value })
              }
              className="border p-2 rounded"
              placeholder="Stock"
            />
          </div>

          <div className="mt-4 space-x-2">
            <button
              onClick={() => handleEdit(editMed.id, editMed)}
              className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700"
            >
              Save Changes
            </button>
            <button
              onClick={() => setEditMed(null)}
              className="bg-gray-400 text-white px-4 py-2 rounded hover:bg-gray-500"
            >
              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default AdminDashboard;
